def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') or 0.0 for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    coord = [0.0] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            if radii[i] > 0 and radii[j] > 0:
                coord[i] += occ[j] * exp(-(d / (1.25 * (radii[i] + radii[j]))) ** 6)
    total = sum(occ[i] for i in range(n) if radii[i] > 0)
    if total <= 0:
        return 0.0
    mean = sum(occ[i] * coord[i] for i in range(n) if radii[i] > 0) / total
    if mean <= 0:
        return 0.0
    variance = sum(occ[i] * (coord[i] - mean) ** 2 for i in range(n) if radii[i] > 0) / total
    return sqrt(variance) / mean

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    elements = [t.get('element') for t in sites]
    radii = [(props.get(e) or {}).get('covalent_radius_A') or 0.0 for e in elements]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    total = 0.0
    unlike = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            if radii[i] > 0 and radii[j] > 0:
