def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') or 0.0 for t in sites]
    en = [(props.get(t.get('element')) or {}).get('eneg') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    weights = [0.0] * n
    contrast = [0.0] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            if radii[i] > 0 and radii[j] > 0 and en[i] is not None and en[j] is not None:
                w = occ[j] * exp(-(d / (1.25 * (radii[i] + radii[j]))) ** 6)
                weights[i] += w
                contrast[i] += w * (en[j] - en[i])
    total = sum(occ[i] for i in range(n) if weights[i] > 0)
    if total <= 0:
        return 0.0
    return sqrt(sum(occ[i] * (contrast[i] / weights[i]) ** 2 for i in range(n) if weights[i] > 0) / total)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') or 0.0 for t in sites]
    ion = [(props.get(t.get('element')) or {}).get('first_ionization_energy_eV') for t in sites]
    affinity = [(props.get(t.get('element')) or {}).get('electron_affinity_eV') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    total = 0.0
    value = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            if radii[i] > 0 and radii[j] > 0:
                gap = inf
                if ion[i] is not None and affinity[j] is not None:
                    gap = ion[i] - affinity[j]
                if ion[j] is not None and affinity[i] is not None:
                    gap = min(gap, ion[j] - affinity[i])
                if isfinite(gap):
                    w = occ[i] * occ[j] * exp(-(d / (1.25 * (radii[i] + radii[j]))) ** 6)
                    total += w
                    value += w * (gap - 14.399645478 / d)
    return value / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    elements = [t.get('element') for t in sites]
    radii = [(props.get(e) or {}).get('covalent_radius_A') or 0.0 for e in elements]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    counts = [{} for i in range(n)]
    weights = [0.0] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            if radii[i] > 0 and radii[j] > 0:
                w = occ[j] * exp(-(d / (1.25 * (radii[i] + radii[j]))) ** 6)
                if w > 0:
                    element = elements[j]
                    counts[i][element] = counts[i].get(element, 0.0) + w
                    weights[i] += w
    total = 0.0
    value = 0.0
    for i in range(n):
        if weights[i] > 0:
            entropy = 0.0
            for count in counts[i].values():
                p = count / weights[i]
                if p > 0:
                    entropy -= p * log(p)
            value += occ[i] * entropy
            total += occ[i]
    return value / total if total > 0 else 0.0
